@import "tailwindcss";
@plugin '@tailwindcss/typography';

@theme {
  --color-white-1: #fcf8ef;
  --color-black-1: #1a1a1a;
  --color-blue-1: #2a9d8f;
  --color-blue-text: #1d756a; /* blue-1 darkened to pass 4.5:1 on white-1 */
  --font-recoleta: 'Recoleta';
}

/* Custom utilities / extended utilities */
@layer utilities {
  .bg-white-1 { background-color: var(--color-white-1); }
  .bg-black-1 { background-color: var(--color-black-1); }
  .bg-blue-1  { background-color: var(--color-blue-1); }

  .text-white-1 { color: var(--color-white-1); }
  .text-black-1 { color: var(--color-black-1); }
  .text-blue-1  { color: var(--color-blue-text); }
  .hover\:text-blue-1:hover, .active\:text-blue-1:active { color: var(--color-blue-text); }

  /* The Recoleta demo font replaces the fi/fl ligatures with a placeholder glyph. */
  .font-recoleta { font-family: var(--font-recoleta); font-variant-ligatures: none; }
}

/* Magnetic hover: one highlight slides between items. Needs no JS. */
.magnetic { position: relative; }
.magnetic-item::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 1.5rem;
  background: color-mix(in srgb, var(--color-blue-1) 50%, transparent);
  opacity: 0;
  transition: opacity 0.15s;
}
/* fallback: per-item highlight */
.magnetic-item:hover::before { opacity: 1; }

@supports (anchor-name: --a) {
  .magnetic-item::before { display: none; }
  .magnetic-item:hover { anchor-name: --magnetic-active; }
  .magnetic:has(.magnetic-item:hover) { --magnetic-on: 1; }
  .magnetic::after {
    content: "";
    position: absolute;
    position-anchor: --magnetic-active;
    inset: anchor(top) anchor(right) anchor(bottom) anchor(left);
    border-radius: 1.5rem;
    background: color-mix(in srgb, var(--color-blue-1) 50%, transparent);
    pointer-events: none;
    opacity: var(--magnetic-on, 0);
    /* leaving: fade after position settles; entering: move, then fade in */
    transition: opacity 0.2s, inset 0.2s 0.2s;
  }
  .magnetic:hover::after { transition: opacity 0.2s 0.2s, inset 0.2s; }
  @media (prefers-reduced-motion: reduce) {
    .magnetic::after { transition: none !important; }
  }
}
@font-face {
  font-family: Recoleta;
  font-style: normal;
  font-weight: 400;
  src: local("Recoleta"), url(/fonts/Recoleta-RegularDEMO.otf) format("opentype");
}
