63	---
64	import { render } from "astro:content";
65	import Layout from "../../layouts/Layout.astro";
66	import ArticleMeta from "../../components/articles/ArticleMeta.astro";
67	import { AUDIO_BASE, socialLinks } from "../../consts";
68	import { getArticles, readingMinutes } from "../../lib/articles";
69	
70	export async function getStaticPaths() {
71	  const articles = await getArticles();
72	  return articles.map((article) => ({ params: { slug: article.id }, props: { article, articles } }));
73	}
74	
75	const { article, articles } = Astro.props;
76	const { title, description, pubDate, updatedDate, tags, narrated, originalAudio, shared } = article.data;
77	const { Content } = await render(article);
78	const more = articles.filter((other) => other.id !== article.id).slice(0, 2);
79	const audio = `${AUDIO_BASE}/${article.id}.mp3`;
80	
81	const url = new URL(Astro.url.pathname, Astro.site);
82	const ogImage = `/og/articles/${article.id}.png`;
83	const minutes = readingMinutes(article);
84	const author = {
85	  "@type": "Person",
86	  name: "Sara Natour",
87	  url: Astro.site,
88	  jobTitle: "Full-stack developer",
89	  sameAs: socialLinks.filter(({ label }) => label !== "email").map(({ url }) => url),
90	};
91	
92	// Structured data for search engines and answer engines: the article itself, and where it sits on the site.
93	const jsonLd = [
94	  {
95	    "@context": "https://schema.org",
96	    "@type": "BlogPosting",
97	    "@id": `${url}#article`,
98	    headline: title,
99	    description,
100	    image: new URL(ogImage, Astro.site),
101	    datePublished: pubDate.toISOString(),
102	    dateModified: (updatedDate ?? pubDate).toISOString(),
103	    author,
104	    publisher: author,
105	    mainEntityOfPage: url,
106	    url,
107	    inLanguage: "en",
108	    wordCount: (article.body ?? "").split(/\s+/).filter(Boolean).length,
109	    timeRequired: `PT${minutes}M`,
110	    isAccessibleForFree: true,
111	    ...(tags.length && { keywords: tags.join(", ") }),
112	    ...(shared.length && { sameAs: shared.map(({ url }) => url) }),
113	    ...(narrated && {
114	      audio: { "@type": "AudioObject", contentUrl: audio, encodingFormat: "audio/mpeg", name: `${title}, read by Sara Natour` },
115	    }),
116	  },
117	  {
118	    "@context": "https://schema.org",
119	    "@type": "BreadcrumbList",
120	    itemListElement: [
121	      { "@type": "ListItem", position: 1, name: "Home", item: Astro.site },
122	      { "@type": "ListItem", position: 2, name: "Articles", item: new URL("/articles", Astro.site) },
123	      { "@type": "ListItem", position: 3, name: title, item: url },
124	    ],
125	  },
126	];
