248	                <span class="text-sm text-[#6b6860]">
249	                  {other.data.pubDate.toLocaleDateString("en", { dateStyle: "medium" })} · {readingMinutes(other)} minute read
250	                </span>
251	                <span class="text-[22px] leading-tight">{other.data.title}</span>
252	                <span class="text-base leading-normal text-[#4a4843]">{other.data.description}</span>
