261	
262	<style is:global>
263	  ::highlight(narration) {
264	    background-color: color-mix(in srgb, var(--color-blue-1) 30%, transparent);
265	  }
266	  /* Thin scrubber: filled up to the playhead (--fill, set by the script), round blue thumb. */
267	  [data-seek] {
268	    appearance: none;
269	    height: 4px;
270	    background: linear-gradient(to right, var(--color-blue-1) var(--fill, 0%), color-mix(in srgb, var(--color-black-1) 12%, transparent) 0);
271	    border-radius: 999px;
272	  }
273	  [data-seek]::-webkit-slider-thumb {
274	    appearance: none;
275	    width: 12px;
276	    height: 12px;
277	    border-radius: 50%;
278	    background: var(--color-blue-1);
279	  }
280	  [data-seek]::-moz-range-thumb {
281	    width: 12px;
282	    height: 12px;
283	    border: 0;
284	    border-radius: 50%;
285	    background: var(--color-blue-1);
286	  }
287	</style>
288	
289	<script>
290	  // Follows the narration: each cue in the .vtt is one sentence; the matching
291	  // sentence on the page is highlighted (CSS Custom Highlight API, no markup added).
292	  const norm = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");
293	
294	  document.addEventListener("astro:page-load", () => {
295	    CSS.highlights?.delete("narration");
296	    const audio = document.querySelector<HTMLAudioElement>("audio[data-narration]");
297	    const article = document.querySelector("article[data-article]");
298	    const track = audio?.textTracks[0];
299	
300	    // Custom player, driving the same <audio> element.
301	    const player = document.querySelector<HTMLElement>("[data-player]");
302	    if (audio && player) {
303	      const q = <T extends Element>(sel: string) => player.querySelector<T>(sel)!;
304	      const play = q<HTMLButtonElement>("[data-play]");
305	      const mute = q<HTMLButtonElement>("[data-mute]");
306	      const seek = q<HTMLInputElement>("[data-seek]");
307	      const time = q<HTMLElement>("[data-time]");
308	      const rate = q<HTMLElement>("[data-rate]");
309	      const speeds = [0.75, 1, 1.25, 1.5, 1.75, 2];
310	      const clock = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
311	      const sync = () => {
312	        const total = Number.isFinite(audio.duration) ? audio.duration : 0;
313	        seek.max = String(total);
314	        seek.value = String(audio.currentTime);
315	        seek.style.setProperty("--fill", `${total ? (audio.currentTime / total) * 100 : 0}%`);
316	        time.textContent = total ? `${clock(audio.currentTime)} / ${clock(total)}` : clock(audio.currentTime);
317	        q("[data-icon-play]").classList.toggle("hidden", !audio.paused);
318	        q("[data-icon-pause]").classList.toggle("hidden", audio.paused);
319	        play.setAttribute("aria-label", audio.paused ? "Play narration" : "Pause narration");
320	        q("[data-icon-sound]").classList.toggle("hidden", audio.muted);
321	        q("[data-icon-muted]").classList.toggle("hidden", !audio.muted);
322	        mute.setAttribute("aria-label", audio.muted ? "Unmute" : "Mute");
323	        rate.textContent = `${audio.playbackRate}x`;
324	      };
325	      // Collapsed to a "Listen" button until asked for; closing pauses and collapses again.
326	      const listen = document.querySelector<HTMLButtonElement>("[data-listen]")!;
327	      const open = (show: boolean) => {
328	        player.hidden = !show;
329	        listen.hidden = show;
330	      };
331	      audio.controls = false;
332	      audio.hidden = true;
333	      open(false);
334	      listen.addEventListener("click", () => {
335	        open(true);
336	        audio.play();
337	        play.focus();
338	      });
339	      q("[data-close]").addEventListener("click", () => {
340	        audio.pause();
341	        open(false);
342	        listen.focus();
343	      });
344	      for (const event of ["loadedmetadata", "timeupdate", "play", "pause", "ended", "volumechange", "ratechange"]) {
345	        audio.addEventListener(event, sync);
346	      }
347	      play.addEventListener("click", () => (audio.paused ? audio.play() : audio.pause()));
348	      mute.addEventListener("click", () => (audio.muted = !audio.muted));
349	      seek.addEventListener("input", () => (audio.currentTime = Number(seek.value)));
350	      for (const button of player.querySelectorAll<HTMLButtonElement>("[data-skip]")) {
351	        button.addEventListener("click", () => {
352	          audio.currentTime = Math.min(Math.max(audio.currentTime + Number(button.dataset.skip), 0), audio.duration || 0);
353	        });
354	      }
355	      for (const button of player.querySelectorAll<HTMLButtonElement>("[data-speed]")) {
356	        button.addEventListener("click", () => {
357	          const i = speeds.indexOf(audio.playbackRate);
358	          const next = speeds[Math.min(Math.max((i < 0 ? 1 : i) + Number(button.dataset.speed), 0), speeds.length - 1)];
359	          audio.playbackRate = next;
360	          audio.defaultPlaybackRate = next; // survives a Krisp / Original switch
361	        });
362	      }
363	      // Krisp / Original: swap the file, keep the position and play state.
364	      const versions = player.querySelectorAll<HTMLButtonElement>("[data-version]");
365	      for (const button of versions) {
366	        button.addEventListener("click", () => {
367	          if (button.getAttribute("aria-checked") === "true") return;
368	          for (const other of versions) other.setAttribute("aria-checked", String(other === button));
369	          const { currentTime, paused } = audio;
370	          audio.src = button.dataset.version!;
371	          audio.addEventListener("loadedmetadata", () => {
372	            audio.currentTime = currentTime;
373	            if (!paused) audio.play();
374	          }, { once: true });
375	        });
376	      }
377	      sync();
378	    }
379	
380	    if (!audio || !article || !track || !CSS.highlights) return; // player only, no highlighting
381	
382	    // One Range per sentence, in page order.
383	    // ponytail: a list item with a nested list yields its nested sentences twice;
384	    // skip blocks containing a nested li if articles start using nested lists.
385	    const segmenter = new Intl.Segmenter("en", { granularity: "sentence" });
386	    const sentences: { key: string; range: Range }[] = [];
387	    for (const block of article.querySelectorAll("p, h2, h3, h4, li")) {
388	      if (block.closest("pre") || block.querySelector("p")) continue;
389	      const walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT);
390	      const nodes: Text[] = [];
391	      while (walker.nextNode()) nodes.push(walker.currentNode as Text);
392	      const at = (offset: number): [Text, number] => {
393	        for (const node of nodes) {
394	          if (offset <= node.length) return [node, offset];
395	          offset -= node.length;
396	        }
397	        return [nodes[nodes.length - 1], nodes[nodes.length - 1].length];
398	      };
399	      for (const { segment, index } of segmenter.segment(block.textContent ?? "")) {
400	        const key = norm(segment);
401	        if (!key) continue;
402	        const range = new Range();
403	        range.setStart(...at(index));
404	        range.setEnd(...at(index + segment.trimEnd().length));
405	        sentences.push({ key, range });
406	      }
407	    }
408	
409	    // Cues are matched to sentences by text, in order, so editing the article
410	    // after recording only un-highlights the edited sentence.
411	    let byCue: Map<TextTrackCue, Range> | undefined;
412	    const matchCues = () => {
413	      byCue = new Map();
414	      let from = 0;
415	      for (const cue of track.cues ?? []) {
416	        const key = norm((cue as VTTCue).getCueAsHTML().textContent ?? "");
417	        const i = sentences.findIndex((s, i) => i >= from && s.key === key);
418	        if (i < 0) continue;
419	        byCue.set(cue, sentences[i].range);
420	        from = i + 1;
421	      }
422	    };
423	
424	    const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
425	    track.mode = "hidden"; // load cues and fire cuechange without rendering them
426	    track.addEventListener("cuechange", () => {
427	      if (!byCue) matchCues();
428	      const cue = track.activeCues?.[0];
429	      const range = cue && byCue!.get(cue);
430	      if (!range) return;
431	      CSS.highlights.set("narration", new Highlight(range));
432	      if (!audio.paused) {
433	        range.startContainer.parentElement?.scrollIntoView({
434	          block: "center",
435	          behavior: reducedMotion.matches ? "auto" : "smooth",
436	        });
437	      }
438	    });
439	
440	    // Dev only: play the recording and press Space as each sentence starts.
441	    // Saving downloads <slug>.vtt, which goes in public/narration/.
442	    const tapButton = import.meta.env.DEV ? document.querySelector<HTMLButtonElement>("button[data-tap]") : null;
443	    if (tapButton) {
444	      const TAP_LAG = 0.2; // seconds a tap trails the voice; tune if highlights feel late or early
445	      const starts: number[] = [];
446	      let tapping = false;
447	      const stamp = (t: number) => new Date(Math.max(t, 0) * 1000).toISOString().slice(11, 23);
448	      const show = () => {
449	        const current = sentences[starts.length - 1];
450	        if (current) {
451	          CSS.highlights.set("narration", new Highlight(current.range));
452	          current.range.startContainer.parentElement?.scrollIntoView({ block: "center" });
453	        } else CSS.highlights.delete("narration");
454	        tapButton.textContent = `${starts.length}/${sentences.length} sentences marked. Space: next sentence starts now. Backspace: undo. Click here to save.`;
455	      };
456	      tapButton.addEventListener("click", () => {
457	        tapButton.blur(); // so Space doesn't re-click the button
458	        if (!tapping) {
459	          tapping = true;
460	          track.mode = "disabled"; // old timings must not fight the taps
461	          starts.length = 0;
462	          audio.currentTime = 0;
463	          audio.play();
464	          show();
465	          return;
466	        }
467	        tapping = false;
468	        audio.pause();
469	        const cues = starts.map((start, i) => {
470	          const text = sentences[i].range.toString().replace(/\s+/g, " ").trim().replace(/&/g, "&amp;").replace(/</g, "&lt;");
471	          return `${stamp(start - TAP_LAG)} --> ${stamp((starts[i + 1] ?? audio.duration + TAP_LAG) - TAP_LAG)}\n${text}\n`;
472	        });
473	        const link = document.createElement("a");
474	        link.href = URL.createObjectURL(new Blob([`WEBVTT\n\n${cues.join("\n")}`], { type: "text/vtt" }));
475	        link.download = `${tapButton.dataset.slug}.vtt`;
476	        link.click();
477	        tapButton.textContent = `Saved ${link.download} to your downloads. Move it to public/narration/ and reload.`;
478	      });
479	      document.addEventListener("keydown", (event) => {
480	        if (!tapping || !tapButton.isConnected) return;
481	        if (event.code === "Space" && starts.length < sentences.length) starts.push(audio.currentTime);
482	        else if (event.code === "Backspace") starts.pop();
483	        else return;
484	        event.preventDefault();
485	        show();
486	      });
487	    }
488	  });
489	</script>
