649	import type { APIRoute, GetStaticPaths } from "astro";
650	import { getArticles, type Article } from "../../../lib/articles";
651	import { articleOgImage } from "../../../lib/og";
652	
653	export const getStaticPaths = (async () =>
654	  (await getArticles()).map((article) => ({ params: { slug: article.id }, props: { article } }))) satisfies GetStaticPaths;
655	
656	export const GET: APIRoute = async ({ props }) =>
657	  new Response(await articleOgImage((props as { article: Article }).article), { headers: { "Content-Type": "image/png" } });
658	// Builds an article's 1200x630 Open Graph card at build time, in the style of public/og/*.png:
659	// black, thin frame lines, Inter. satori lays it out as SVG, sharp turns it into PNG.
660	import { readFile } from "node:fs/promises";
661	import satori from "satori";
662	import sharp from "sharp";
663	import { readingMinutes, type Article } from "./articles";
664	
665	type Node = { type: string; props: Record<string, unknown> };
666	const el = (type: string, style: Record<string, unknown>, children?: unknown): Node => ({
667	  type,
668	  props: { style, children },
669	});
670	
671	let fonts: Promise<{ name: string; data: Buffer; weight: 400 | 600; style: "normal" }[]> | undefined;
672	const loadFonts = () =>
673	  (fonts ??= Promise.all(
674	    ([[400, "Regular"], [600, "SemiBold"]] as const).map(async ([weight, file]) => ({
675	      name: "Inter",
676	      data: await readFile(`src/assets/fonts/Inter-${file}.ttf`),
677	      weight,
678	      style: "normal" as const,
679	    })),
680	  ));
681	
682	const clip = (text: string, max: number) => (text.length > max ? `${text.slice(0, max - 1).trimEnd()}…` : text);
683	
684	export async function articleOgImage(article: Article): Promise<ArrayBuffer> {
685	  const { title, description, pubDate, narrated } = article.data;
686	  const line = "#3a3a3a";
687	  const date = pubDate.toLocaleDateString("en", { dateStyle: "medium" });
688	
689	  const card = el(
690	    "div",
691	    {
692	      width: 1200,
693	      height: 630,
694	      display: "flex",
695	      position: "relative",
696	      background: "#000",
697	      fontFamily: "Inter",
698	      color: "#fff",
699	    },
700	    [
701	      el("div", { position: "absolute", top: 64, left: 0, width: 1200, height: 1, background: line }),
702	      el("div", { position: "absolute", bottom: 64, left: 0, width: 1200, height: 1, background: line }),
703	      el("div", { position: "absolute", left: 64, top: 0, width: 1, height: 630, background: line }),
704	      el("div", { position: "absolute", right: 64, top: 0, width: 1, height: 630, background: line }),
705	      el(
706	        "div",
707	        { position: "absolute", top: 112, left: 130, right: 130, bottom: 104, display: "flex", flexDirection: "column" },
708	        [
709	          el("div", { fontSize: 26, color: "#8a8a8a" }, "saranatour.dev / articles"),
710	          el(
711	            "div",
712	            { marginTop: 24, fontSize: title.length > 48 ? 56 : 68, fontWeight: 600, lineHeight: 1.1, letterSpacing: -1 },
713	            clip(title, 90),
714	          ),
715	          el("div", { marginTop: 22, fontSize: 28, lineHeight: 1.4, color: "#9a9a9a" }, clip(description, 120)),
716	          el("div", { flexGrow: 1 }),
717	          el("div", { width: 560, borderTop: "2px dashed #444", marginBottom: 26 }),
718	          el("div", { display: "flex", alignItems: "center", gap: 18, fontSize: 26 }, [
719	            el("div", { color: "#fff" }, "Sara Natour"),
720	            el("div", { color: "#8a8a8a" }, `${date} · ${readingMinutes(article)} min read`),
721	            ...(narrated ? [el("div", { color: "#2a9d8f" }, "· With audio")] : []),
722	          ]),
723	        ],
724	      ),
725	    ],
726	  );
727	
728	  const svg = await satori(card as never, { width: 1200, height: 630, fonts: await loadFonts() });
729	  const png = await sharp(Buffer.from(svg)).png().toBuffer();
730	  return png.buffer.slice(png.byteOffset, png.byteOffset + png.byteLength) as ArrayBuffer;
731	}
