// Builds the Open Graph cards at build time, in the homepage's look: cream ground, a teal
// rounded frame, Recoleta, the grey hand-drawn doodles. satori lays them out as SVG, sharp turns it into PNG.
import { readFile } from "node:fs/promises";
import satori from "satori";
import sharp from "sharp";
import { readingMinutes, type Article } from "./articles";

type Node = { type: string; props: Record<string, unknown> };
const el = (type: string, style: Record<string, unknown>, children?: unknown): Node => ({
  type,
  props: { style, children },
});

const ink = "#1a1a1a";
const body = "#4a4843";
const muted = "#6b6860";
const teal = "#2a9d8f"; // the card border
const tealText = "#1d756a"; // teal that passes 4.5:1 on the cream

// The homepage's Smily and Heart icons (src/components/Icons).
const SMILY = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 126 138" fill="none" stroke="#999" stroke-width="5" stroke-linecap="round"><path d="M41.415 66.638C41.415 67.654 41.122 69.39 42.621 69.39C43.635 69.39 45.145 68.037 45.203 66.982C45.265 65.875 45.041 64.574 43.654 64.574C42.904 64.574 41.057 64.256 40.726 64.918M76.202 63.541C76.202 65.768 75.913 67.317 78.767 66.561C80.82 66.019 83.436 64.364 83.436 61.993C83.436 59.224 81.101 59.413 78.958 59.413C76.889 59.413 77.58 61.96 77.58 63.541M24.537 86.593C30.682 92.172 36.278 98.044 44.209 101.158C49.42 103.205 55.301 102.764 60.779 102.764C67.156 102.764 72.485 100.923 77.963 97.68C88.004 91.734 98.735 83.23 104.522 72.87C106.994 68.444 107.62 64.203 108.579 59.413"/><path d="M47.084 36.922C35.57 36.922 28.438 39.099 19.85 47.626C9.976 57.432 4.786 69.445 3.23 83.019C1.745 95.976 2.049 107.71 11.267 117.63C25.85 133.321 50.781 136.794 71.119 134.896C88.897 133.236 107.063 122.271 115.52 106.105C125.151 87.696 125.797 62.476 118.563 43.251C114.57 32.64 107.572 23.551 99.055 16.14C89.728 8.025 78.284 5.146 66.241 3.639C49.826 1.585 32.285 2.176 17.588 10.202"/></svg>`;
const HEART = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 41 71" fill="none" stroke="#999" stroke-width="5" stroke-linecap="round"><path d="M26.415 56.557C24.554 56.557 24.231 55.241 22.91 54.127C18.848 50.7 15.387 45.961 12.585 41.487C8.75 35.365 5.13 28.618 3.503 21.557C2.843 18.687 2.862 14.043 3.39 11.16C4.162 6.95 6.91 11.579 8.1 12.507C12.837 16.2 16.035 24.376 17.635 29.932C18.232 32.008 19.632 33.416 19.632 30.157C19.632 24.515 20.946 20.476 23.551 15.498C24.928 12.866 32.854 -1.991 36.439 4.728C38.439 8.479 37.946 12.74 37.946 17.181C37.946 26.526 33.937 35.306 31.126 44.142C29.376 49.64 27.538 55.384 25.058 60.596C24.372 62.037 23.455 67.449 22.345 68"/></svg>`;
const doodle = (svg: string, width: number, height: number, style: Record<string, unknown>): Node => ({
  type: "img",
  props: { src: `data:image/svg+xml,${encodeURIComponent(svg)}`, width, height, style },
});

// The homepage card: cream page, 2px teal border, rounded corners.
const card = (height: number, style: Record<string, unknown>, children: Node[]) =>
  el("div", { width: 1200, height, display: "flex", padding: 40, background: "#fcf8ef", color: ink, fontFamily: "Recoleta" }, [
    // explicit size: satori doesn't shrink a flexGrow child by the parent's padding
    el("div", { width: 1120, height: height - 80, display: "flex", position: "relative", border: `2px solid ${teal}`, borderRadius: 28, ...style }, children),
  ]);

let font: Promise<Buffer> | undefined;
async function png(node: Node, height: number): Promise<ArrayBuffer> {
  const data = await (font ??= readFile("public/fonts/Recoleta-RegularDEMO.otf"));
  const svg = await satori(node as never, { width: 1200, height, fonts: [{ name: "Recoleta", data, weight: 400, style: "normal" }] });
  const out = await sharp(Buffer.from(svg)).png().toBuffer();
  return out.buffer.slice(out.byteOffset, out.byteOffset + out.byteLength) as ArrayBuffer;
}

const clip = (text: string, max: number) => (text.length > max ? `${text.slice(0, max - 1).trimEnd()}…` : text);

/** The card for every page that isn't an article. Platforms crop to different ratios, so the height varies. */
export const siteOgImage = (height: number) =>
  png(
    card(height, { padding: "0 88px", alignItems: "center", justifyContent: "space-between" }, [
      el("div", { display: "flex", flexDirection: "column" }, [
        el("div", { fontSize: 140, lineHeight: 0.95, letterSpacing: -1.4 }, "Sara"),
        el("div", { fontSize: 140, lineHeight: 0.95, letterSpacing: -1.4 }, "Natour"),
        el("div", { marginTop: 28, fontSize: 34, color: body }, "Full-stack developer x Electrical Engineer"),
        el("div", { marginTop: 44, fontSize: 28, color: tealText }, "saranatour.dev"),
      ]),
      el("div", { position: "relative", display: "flex", width: 250, height: 300 }, [
        doodle(SMILY, 200, 219, { position: "absolute", left: 10, top: 50 }),
        doodle(HEART, 34, 59, { position: "absolute", right: 0, top: 0, transform: "rotate(12deg)" }),
        doodle(HEART, 28, 48, { position: "absolute", left: 0, bottom: 0, transform: "rotate(-12deg)" }),
      ]),
    ]),
    height,
  );

/** An article's 1200x630 card. */
export async function articleOgImage(article: Article): Promise<ArrayBuffer> {
  const { title, description, pubDate, narrated } = article.data;
  const date = pubDate.toLocaleDateString("en", { dateStyle: "medium" });

  return png(
    card(630, { flexDirection: "column", padding: "60px 80px 56px" }, [
      doodle(HEART, 30, 52, { position: "absolute", right: 72, top: 48, transform: "rotate(12deg)" }),
      doodle(SMILY, 92, 101, { position: "absolute", right: 64, bottom: 44 }),
      el("div", { fontSize: 26, color: muted }, "saranatour.dev / articles"),
      el(
        "div",
        { marginTop: 28, maxWidth: 880, fontSize: title.length > 40 ? 56 : 76, lineHeight: 1.05, letterSpacing: -0.8 },
        clip(title, 80),
      ),
      el("div", { marginTop: 24, maxWidth: 820, fontSize: 28, lineHeight: 1.4, color: body }, clip(description, 110)),
      el("div", { flexGrow: 1 }),
      el("div", { display: "flex", gap: 16, fontSize: 26 }, [
        el("div", {}, "Sara Natour"),
        el("div", { color: muted }, `${date} · ${readingMinutes(article)} min read`),
        ...(narrated ? [el("div", { color: tealText }, "· With audio")] : []),
      ]),
    ]),
    630,
  );
}

