import { readFile, writeFile } from 'node:fs/promises';
import { defineConfig } from 'astro/config';
import sitemap from '@astrojs/sitemap';
import tailwindcss from "@tailwindcss/vite";
import TurndownService from 'turndown';

// Writes a .md twin next to each built page; worker.ts serves it for Accept: text/markdown.
const markdownPages = {
  name: 'markdown-pages',
  hooks: {
    'astro:build:done': async ({ dir, pages }) => {
      const turndown = new TurndownService({ headingStyle: 'atx' }).remove(['svg', 'style', 'script']);
      // Every img is a decorative icon. A rule, because remove() loses to turndown's built-in img rule.
      turndown.addRule('noImages', { filter: 'img', replacement: () => '' });
      // Project cards wrap a whole heading in <a>; [### x](url) isn't valid markdown, ### [x](url) is.
      turndown.addRule('cardLink', {
        filter: (node) => node.nodeName === 'A' && node.querySelector('h1,h2,h3,h4,h5,h6'),
        replacement: (content, node) => `\n\n${content.trim().replace(/^(#+ )(.*)$/m, `$1[$2](${node.getAttribute('href')})`)}\n\n`,
      });
      for (const { pathname } of pages) {
        const html = await readFile(new URL(`${pathname}index.html`, dir), 'utf8');
        const main = html.match(/<main[\s\S]*<\/main>/)?.[0];
        if (!main) throw new Error(`markdown-pages: no <main> in /${pathname}`);
        // Through turndown to decode entities like &#39;.
        const title = turndown.turndown(html.match(/<title>(.*?)<\/title>/)?.[1] ?? '');
        const description = turndown.turndown(html.match(/<meta name="description" content="(.*?)"/)?.[1] ?? '');
        // JSON strings are valid YAML, so titles with colons or quotes stay safe.
        const frontmatter = `---\ntitle: ${JSON.stringify(title)}\ndescription: ${JSON.stringify(description)}\n---`;
        const file = `${pathname.replace(/\/$/, '') || 'index'}.md`;
        // Flexbox spaces the contact links in HTML; in text they'd run together.
        const body = turndown.turndown(main).replaceAll(')[', ') [');
        await writeFile(new URL(file, dir), `${frontmatter}\n\n${body}\n`);
      }
    },
  },
};

// https://astro.build/config
export default defineConfig({
  site: 'https://saranatour.dev/',
  integrations: [sitemap(), markdownPages],

  vite: {
    plugins: [tailwindcss()]
  }
});
import { trackAgents } from "@databuddy/sdk/agents";
import { prefersMarkdown } from "./src/lib/accept";
import { DATABUDDY_WEBSITE_ID } from "./src/lib/databuddy";

// ponytail: inline types instead of adding @cloudflare/workers-types for one file
interface Env {
	ASSETS: { fetch(request: Request): Promise<Response> };
}

export default {
	async fetch(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
		ctx.waitUntil(trackAgents(request, { websiteId: DATABUDDY_WEBSITE_ID }));
		if (["GET", "HEAD"].includes(request.method) && prefersMarkdown(request.headers.get("accept") ?? "")) {
			const url = new URL(request.url);
			const path = url.pathname.replace(/\/$/, "") || "/index";
			const asset = await env.ASSETS.fetch(new Request(new URL(`${path}.md`, url)));
			// No .md twin (images, llms.txt, 404s): fall through to the normal response.
			if (asset.ok) {
				const markdown = await asset.text();
				const headers = new Headers(asset.headers);
				headers.set("Content-Type", "text/markdown; charset=utf-8");
				headers.set("Vary", "Accept");
				// ponytail: ~4 chars per token estimate, a real tokenizer isn't worth the bundle size
				headers.set("x-markdown-tokens", String(Math.ceil(markdown.length / 4)));
				// Same policy as robots.txt.
				headers.set("Content-Signal", "ai-train=no, search=yes, ai-input=yes");
				return new Response(markdown, { headers });
			}
		}
		// Assets-only site: no origin to fetch(request) from, serve dist/ instead.
		return env.ASSETS.fetch(request);
	},
};
{
	"name": "site",
	"compatibility_date": "2026-06-12",
	"main": "./worker.ts",
	"assets": {
		"directory": "./dist",
		"binding": "ASSETS",
		// Without this, static hits skip the worker and never get tracked.
		"run_worker_first": true
	},
	// Required by `wrangler preview` (PR preview deploys). Empty: previews use the same settings as production.
	"previews": {},
	"observability": {
		"enabled": false,
		"head_sampling_rate": 1,
		"redact_query_string": false,
		"logs": {
			"enabled": true,
			"head_sampling_rate": 1,
			"invocation_logs": true,
			"persist": true
		},
		"traces": {
			"enabled": true,
			"head_sampling_rate": 1,
			"persist": true
		},
		// The dashboard calls this "issue_detection"; wrangler's key is "issues".
		"issues": {
			"enabled": true
		}
	}
}
