// Prints each report's category scores and every scored audit below 1.
import { readdirSync, readFileSync } from "node:fs";

const dir = process.argv[2];
for (const file of readdirSync(dir).filter((f) => f.endsWith(".json")).sort()) {
  const lhr = JSON.parse(readFileSync(`${dir}/${file}`, "utf8"));
  const scores = Object.values(lhr.categories).map((c) => `${c.id}=${Math.round(c.score * 100)}`).join(" ");
  console.log(`\n${file.replace(".json", "")}: ${scores}`);
  const scored = new Set(Object.values(lhr.categories).flatMap((c) => c.auditRefs.filter((r) => r.weight > 0).map((r) => r.id)));
  for (const a of Object.values(lhr.audits)) {
    if (scored.has(a.id) && a.score !== null && a.score < 1) {
      console.log(`  ${a.id} (${a.score}) ${a.displayValue ?? ""} — ${a.title}`);
    }
  }
}

